ALTER TABLE "subscription_payments" ADD COLUMN "number" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY (sequence name "subscription_payments_number_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1001 CACHE 1);--> statement-breakpoint
UPDATE "subscription_payments" p SET "number" = o.n FROM (SELECT "id", 1000 + row_number() OVER (ORDER BY "created_at", "id") AS n FROM "subscription_payments") o WHERE p."id" = o."id";--> statement-breakpoint
SELECT setval('"subscription_payments_number_seq"', 1000 + (SELECT count(*) FROM "subscription_payments"), true);--> statement-breakpoint
ALTER TABLE "subscription_payments" ADD CONSTRAINT "subscription_payments_number_unique" UNIQUE("number");
